-- Mod-authored era change splash descriptions, ru_RU overlay.
-- Baseline in CivVAccess_EraDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_MISSING"] = "Для этой эры нет описания."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_CLASSICAL"] =
    "Величественный храм с колоннами венчает террасированную вершину холма; меньшие залы с колоннадами ступенями спускаются вправо. Ниже по склону разбиты сады, среди которых вьются узкие лестницы мимо светлого скалистого уступа, поросшего кипарисами и цветущими кустарниками. Весь мрамор светится тёплым золотом в лучах солнца."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MEDIEVAL"] =
    "Золотые пшеничные поля расстилаются под обнесённым стеной городом с бледными башнями на холме. С зубцов свисают красные знамёна; на самом большом изображена чёрная птица с распростёртыми крыльями. На дворе страда: согнувшиеся крестьяне вяжут срезанный хлеб, другие несут на спинах высокие снопы, а работники в центре грузят телегу, запряжённую парой тёмных волов. Деревья наклоняются к сцене с обоих верхних углов под мягким дымчатым небом."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_RENAISSANCE"] =
    "Высоко над черепичными крышами Флоренции Микеланджело стоит на деревянной лестнице, вырубая колоссального белого мраморного Давида. Голова и плечи статуи одни занимают левую часть картины; скульптор едва достаёт до её плеча. Внизу красные черепичные крыши уходят вдаль к великому куполу собора Санта-Мария-дель-Фьоре и стройной колокольне. За ними сквозь грозовое тёмное небо пробивается золотой свет."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_INDUSTRIAL"] =
    "Красно-белый колёсный пароход пересекает Нью-Йоркскую гавань на переднем плане, тянув за собой дым из двух чёрных труб. Пассажиры выстроились вдоль двух палуб. За ним Статуя Свободы поднимается зелёной на фоне дымчатого янтарного неба; дальше по воде дымят другие суда. Дым и дымка окрашивают всю сцену в тёплую сепию и золото."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MODERN"] =
    "Смотришь с крыши высотного здания через весь город, полный таких же башен. Освещённые небоскрёбы уходят квартал за кварталом в золотистую дымку. Далеко внизу эстакадные шоссе петлями вьются через развязку, по изгибам которой бегут потоки автомобилей и грузовиков. Вся картина одного цвета, золота и сепии, как тонированная фотография."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_POSTMODERN"] =
    "Низкое солнце пылает в дальнем конце улицы середины прошлого века, заливая её золотым светом. Мужчины в костюмах и шляпах идут по правому тротуару спиной к смотрящему мимо навесов и большой буквенной вывески. Округлые тёмные седаны припаркованы у обочины или катятся мимо. Впереди здания растворяются в слепящем свете."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_FUTURE"] =
    "Футуристический город сверкает вдоль золотистого побережья, его стройные башни уходят берегом в дымку. Слева изящный красно-белый самолёт закладывает вираж над водой; за ним висячий мост перекидывается через залив. На переднем плане справа купольный комплекс из хрома и стекла встроен прямо в морские скалы. Уступы его украшает зелень; на прогулочной дорожке стоит одинокая фигура."
